// EP19 helpers shared by the scene modules: beat-map timing, Garuda emblem, A4 pages,
// ruler, snap easing, background drift and screen shake. Built on window.NSP (shared engine).
(function () {
  const { clamp, lerp, E, P, tf, h } = NSP;
  const TL = window.TL, BT = window.BEATS;

  // ---- timing from the measured beat map (source/beats.js, generated by tools/beatmap.py) ----
  const S = k => TL[k][0];                       // segment start (s, absolute)
  const D = k => TL[k][1];                       // segment length
  const B = (k, i) => S(k) + BT[k][i][0];        // start of voiced run i
  const Be = (k, i) => S(k) + BT[k][i][1];       // end of voiced run i
  // time of a word inside a run, by its share of spacing characters (Thai combining marks don't count)
  const SKIP = /[ัิ-ฺ็-๎\s.!?"…,]/;
  const len = s => [...s].filter(c => !SKIP.test(c)).length;
  function W(k, i, word) {
    const [a, b, lab] = BT[k][i]; const j = lab.indexOf(word);
    if (j < 0) throw new Error(`beat word "${word}" not in "${lab}"`);
    return S(k) + a + (b - a) * len(lab.slice(0, j)) / len(lab);
  }

  // ---- Garuda emblem: one artwork (assets/garuda.svg) referenced everywhere via <use> ----
  const xhr = new XMLHttpRequest();
  xhr.open('GET', '../assets/garuda.svg', false); xhr.send();
  const art = xhr.responseText.match(/<g id="half"[\s\S]*?<\/g>/);
  if (!art) throw new Error('garuda.svg not loaded');
  document.body.insertAdjacentHTML('afterbegin', `<svg width="0" height="0" style="position:absolute"><defs>${art[0]}
    <g id="garuda"><use href="#half"/><use href="#half" transform="translate(120 0) scale(-1 1)"/></g></defs></svg>`);
  const GR = 120 / 132;                          // width / height of the emblem
  // emblem whose drawn height is hpx; positioned by its top-left (use .ctr + translate to centre)
  const gar = (hpx, color = '#0E1526', cls = '') =>
    `<svg class="gar ${cls}" viewBox="0 0 120 132" style="width:${(hpx * GR).toFixed(1)}px;height:${hpx}px;color:${color}"><use href="#garuda"/></svg>`;

  // ---- A4 page (210 × 297). Text lines are drawn in the body area only. ----
  function a4(w, { lines = true, top = .36, rows = 12 } = {}) {
    const hgt = Math.round(w * 297 / 210);
    const el = h(`<div class="a4" style="width:${w}px;height:${hgt}px"></div>`);
    if (lines) for (let i = 0; i < rows; i++) {
      const y = hgt * top + i * hgt * (.56 / rows), ind = i === 0 || i === 6 ? w * .14 : w * .1;
      const ww = (i === 5 || i === rows - 1) ? w * .45 : w * (.8 - (i % 3) * .03) - (ind - w * .1);
      el.appendChild(h(`<div class="ln" style="left:${ind}px;top:${y}px;width:${ww}px"></div>`));
    }
    el.w = w; el.h = hgt;
    return el;
  }

  // ---- vertical ruler: n cm at pxcm px per cm (ticks every mm), zero at the bottom ----
  function ruler(n, pxcm) {
    const H = n * pxcm, Wd = 46;
    let t = '';
    for (let mm = 0; mm <= n * 10; mm++) {
      const y = H - mm * pxcm / 10, L = mm % 10 === 0 ? 30 : mm % 5 === 0 ? 20 : 11;
      t += `<line x1="${Wd}" y1="${y.toFixed(1)}" x2="${Wd - L}" y2="${y.toFixed(1)}" stroke="#0E1526" stroke-width="${mm % 10 === 0 ? 3 : 1.6}"/>`;
    }
    return `<svg width="${Wd + 8}" height="${H + 24}" viewBox="-4 -12 ${Wd + 8} ${H + 24}" style="position:absolute;overflow:visible">
      <rect x="-4" y="-12" width="${Wd + 8}" height="${H + 24}" rx="8" fill="#FFE58A" stroke="#C9A227" stroke-width="2"/>${t}</svg>`;
  }

  // spring-like snap: overshoots the target by 3.5 % of the travel, then settles (spec: <= 4 %)
  const snap = x => x <= 0 ? 0 : x >= 1 ? 1 : x < .6 ? 1.035 * E.out(x / .6) : 1.035 - .035 * E.inOut((x - .6) / .4);
  // place an element (top-left anchored, known size) by its centre
  function at(el, cx, cy, { s = 1, r = 0, o = 1, sx, sy } = {}) {
    tf(el, { x: cx - el._w / 2, y: cy - el._h / 2, s, r, o, sx, sy });
  }
  function sized(el, w, hh) { el._w = w; el._h = hh; el.style.transformOrigin = '50% 50%'; return el; }

  // ---- background: blueprint grid drift + slow floating marks (continuous micro-motion) ----
  const bp = document.getElementById('bp'), fx = document.getElementById('bpfx');
  let seed = 7; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
  const marks = [];
  for (let i = 0; i < 26; i++) {
    const kind = i % 3, el = h(kind ? `<div class="bpx">${kind === 1 ? '+' : '×'}</div>` : `<div class="bpd" style="width:${6 + rnd() * 8}px;height:${6 + rnd() * 8}px"></div>`);
    fx.appendChild(el); marks.push({ el, x: rnd() * 1080, y: rnd() * 1920, sp: 10 + rnd() * 22, ph: rnd() * 6.28 });
  }
  function drawBg(t) {
    bp.style.transform = `translate(${(-t * 9) % 120}px,${(-t * 14) % 120}px)`;
    marks.forEach(m => { let y = (m.y - t * m.sp) % 2000; if (y < -40) y += 2000; tf(m.el, { x: m.x + Math.sin(t * .5 + m.ph) * 18, y, o: .25 + .2 * Math.sin(t * 1.1 + m.ph), r: t * 10 }); });
  }

  // ---- screen shake events (stamp slam): amplitude <= 6 px, <= 8 frames ----
  const shakes = [];
  const shake = (at0, amp = 6, frames = 8) => shakes.push({ at0, amp: Math.min(6, amp), dur: Math.min(8, frames) / TL.fps });
  function drawShake(t) {
    let x = 0, y = 0;
    for (const s of shakes) { const u = t - s.at0; if (u >= 0 && u < s.dur) { const k = s.amp * (1 - u / s.dur); x += Math.sin(u * 95) * k; y += Math.cos(u * 77) * k * .6; } }
    document.getElementById('stage').style.transform = x || y ? `translate(${x.toFixed(2)}px,${y.toFixed(2)}px)` : '';
  }

  // ---- static two-page comparison (same geometry as scene 4's side-by-side layout), used by the answer recap ----
  // external letter: 3 cm emblem centred, 2.5 cm from the top; memo: 1.5 cm emblem top-left + "บันทึกข้อความ"
  function comparePages(parent) {
    const PW = 350, CMP = PW / 21 * 2, GL = 3 * CMP, GS = 1.5 * CMP, GAP = 2.5 * CMP;
    const L = a4(PW, { top: .42, rows: 10 }), R = a4(PW, { top: .3, rows: 13 });
    L.insertAdjacentHTML('beforeend', `<div class="abs" style="left:${PW / 2 - 2}px;top:0;width:4px;height:${L.h}px;background:repeating-linear-gradient(180deg,#14B8D6 0 14px,transparent 14px 24px);opacity:.45"></div>
      <div class="abs cp-gl" style="left:${PW / 2 - GL * GR / 2}px;top:${GAP}px;width:${GL * GR}px;height:${GL}px;transform-origin:50% 50%">${gar(GL)}</div>`);
    R.insertAdjacentHTML('beforeend', `<div class="abs cp-gs" style="left:18px;top:24px;width:${GS * GR}px;height:${GS}px;transform-origin:50% 50%">${gar(GS)}</div>
      <div class="ttl" style="left:${18 + GS * GR + 9}px;top:${24 + GS / 2}px;translate:0 -50%;font-size:42px">บันทึกข้อความ</div>
      ${[[22, 92, 300], [22, 122, 160], [190, 122, 132], [22, 152, 300]].map(([x, y, ww]) => `<div class="ln" style="left:${x}px;top:${y}px;width:${ww}px;height:8px;background:#C9D2E1"></div>`).join('')}`);
    L.style.left = '160px'; R.style.left = '540px'; L.style.top = R.style.top = '520px';
    const ll = h(`<div class="abs" style="left:355px;top:428px;width:0;height:0"><div class="pill2 p-eb kt" style="position:absolute;left:0;top:0;translate:-50% 0;font-size:42px">หนังสือภายนอก</div></div>`);
    const lr = h(`<div class="abs" style="left:712px;top:428px;width:0;height:0"><div class="pill2 p-cy kt" style="position:absolute;left:0;top:0;translate:-50% 0;font-size:42px">บันทึกข้อความ</div></div>`);
    [L, R, ll, lr].forEach(e => parent.appendChild(e));
    return { L, R, ll, lr, gl: L.querySelector('.cp-gl'), gs: R.querySelector('.cp-gs') };
  }

  const X = { S, D, B, Be, W, gar, GR, a4, ruler, snap, at, sized, drawBg, shake, drawShake, comparePages };
  window.EP19 = X;
})();
